def comps(b,color):
    seen=set(); cs=[]
    for r in range(4):
        for c in range(4):
            if b[r][c]==color and (r,c) not in seen:
                st=[(r,c)]; cells=[]
                while st:
                    x,y=st.pop()
                    if (x,y) in seen: continue
                    seen.add((x,y)); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a2,b2=x+dx,y+dy
                            if 0<=a2<4 and 0<=b2<4 and b[a2][b2]==color: st.append((a2,b2))
                cs.append(cells)
    return cs
